// Polls: a teacher sends a link to the students, who give their
// availabilities; the teacher imports them into their project. No DOM here:
// the functions are tested with Node.
//
// The server (see 'server/api.js') only stores encrypted data: the
// definition of the poll and the responses are encrypted with AES-GCM in the
// browsers, with a key which is in the link, after '#': browsers don't send
// it to the server.
//
// There are two kinds of links:
// - the personal link of a student of the project: it contains the id and the
//   token of their response (generated by the browser of the teacher), so
//   the student can give and modify their availabilities from any device,
//   and their response is imported for them;
// - the shared link, for the students who aren't in the project yet: they
//   give their name, and their response is imported for the student of the
//   same name, or for a new student. Once they answered, they get their
//   personal link.
//
// Each project has a poll ('project.poll', see 'newPoll'): its id, its key and
// the links of the students are generated by the browser of the teacher, so
// they exist as soon as the students are added to the project. The poll is
// created on the server, and updated when what the students see changes, by
// 'publishPoll'.
//
//     {
//         id, key, adminToken,
//         message,       // the message of the teacher to the students
//         signature,     // see 'definitionSignature', when last sent
//         closed,
//         created,       // when it was created on the server, 0 if not yet
//         lastImport,    // the summary of the last import (see 'importResponses')
//     }
//
// The definition of a poll (decrypted), seen by the students:
//
//     {version, title, teacher, message, calendar, teacherAvailability}
//
// A response (decrypted):
//
//     {version, name, availability, comment}
//
// The fields of the participants of a project about the poll:
//
//     pollLink: {pollId, responseId, token},  // their personal link
//     pollResponseIds: [responseId],          // the responses imported for them
//     pollUpdated,                            // the date of the last one
//     comment,                                // its comment

import {ApiError, decrypt, encrypt, generateKey, randomToken} from "./client.js";
import * as model from "./model.js";

const FORMAT_VERSION = 1;

/////////////////////////////////////////////////////////////////////////////
// Links
/////////////////////////////////////////////////////////////////////////////

// The link of a poll for the students, relative to the page of the teacher.
export function pollLink(pageUrl, pollId, key) {
    const url = new URL("poll.html", pageUrl);
    url.hash = `p=${pollId}&k=${key}`;
    return url.href;
}

// The personal link of a student: with the id and the token of their
// response, and their name.
export function personalLink(pageUrl, pollId, key, {responseId, token}, name) {
    const url = new URL(pollLink(pageUrl, pollId, key));
    url.hash += "&" + new URLSearchParams({r: responseId, t: token, n: name}).toString();
    return url.href;
}

const TOKEN = /^[A-Za-z0-9_-]{22,64}$/;

// '{pollId, key}' of the hash of a link ('#p=...&k=...'), and
// '{responseId, token, name}' for a personal link, or null.
export function parsePollLink(hash) {
    const parameters = new URLSearchParams(hash.replace(/^#/, ""));
    const pollId = parameters.get("p");
    const key = parameters.get("k");
    if (!TOKEN.test(pollId || "") || !/^[A-Za-z0-9_-]{43}$/.test(key || ""))
        return null;
    const link = {pollId, key};
    if (parameters.has("r") || parameters.has("t")) {
        const responseId = parameters.get("r");
        const token = parameters.get("t");
        if (!TOKEN.test(responseId || "") || !TOKEN.test(token || ""))
            return null;
        Object.assign(link, {responseId, token, name: (parameters.get("n") || "").slice(0, 100)});
    }
    return link;
}

/////////////////////////////////////////////////////////////////////////////
// Teacher
/////////////////////////////////////////////////////////////////////////////

// The definition of the poll of a project.
export function pollDefinition(project, message) {
    const teacher = model.teacherOf(project);
    return {
        version: FORMAT_VERSION,
        title: project.name,
        teacher: teacher === null? "": teacher.name,
        message,
        calendar: project.calendar,
        teacherAvailability: teacher === null? {}: teacher.availability,
    };
}

// What the students see of a project: when it changes, the poll has to be
// updated (see 'publishPoll').
export function definitionSignature(project) {
    return JSON.stringify(pollDefinition(project, project.poll === null? "": project.poll.message));
}

// 'true' if the poll has to be created or updated on the server.
export function needsPublish(project) {
    return project.poll !== null
        && (project.poll.created === 0 || project.poll.signature !== definitionSignature(project));
}

// Give a new poll to a project, and links to its students. It is created on
// the server by 'publishPoll'.
export function newPoll(project, message = "") {
    project.poll = {
        id: randomToken(),
        key: generateKey(),
        adminToken: randomToken(),
        message,
        signature: "",
        closed: false,
        created: 0,
        lastImport: null,
    };
    ensurePersonalLinks(project);
}

// Create the poll on the server, or send its current definition (the week,
// the availabilities of the teacher, their message). Returns 'true' if
// something was sent.
export async function publishPoll(api, project) {
    if (!needsPublish(project))
        return false;
    const {poll} = project;
    const definition = pollDefinition(project, poll.message);
    const changes = {definition: await encrypt(poll.key, definition)};
    if (poll.created === 0)
        changes.closed = poll.closed;
    await api.updatePoll(poll.id, poll.adminToken, changes);
    if (poll.created === 0)
        poll.created = Date.now();
    poll.signature = JSON.stringify(definition);
    return true;
}

// Give a personal link to the students of the project who don't have one for
// its poll (e.g. added since it was created). Returns 'true' if a link was
// added.
export function ensurePersonalLinks(project) {
    if (project.poll === null)
        return false;
    let added = false;
    for (const participant of project.participants) {
        if (participant.role === "teacher"
                || (participant.pollLink !== undefined && participant.pollLink.pollId === project.poll.id))
            continue;
        participant.pollLink = {pollId: project.poll.id, responseId: randomToken(), token: randomToken()};
        added = true;
    }
    return added;
}

// The personal link of a participant, or null.
export function participantLink(pageUrl, project, participant) {
    const {poll} = project;
    if (poll === null || participant.pollLink === undefined || participant.pollLink.pollId !== poll.id)
        return null;
    return personalLink(pageUrl, poll.id, poll.key, participant.pollLink, participant.name);
}

// Remove the fields of the participants about the poll of a project.
function forgetPoll(project) {
    for (const participant of project.participants) {
        delete participant.pollLink;
        delete participant.pollResponseIds;
        delete participant.pollUpdated;
    }
}

export async function setPollClosed(api, project, closed) {
    const {poll} = project;
    // Not created yet: created closed (see 'publishPoll').
    if (poll.created !== 0)
        await api.updatePoll(poll.id, poll.adminToken, {closed});
    poll.closed = closed;
}

// Delete the poll and its responses from the server.
export async function deletePoll(api, project) {
    const {poll} = project;
    try {
        if (poll.created !== 0)
            await api.deletePoll(poll.id, poll.adminToken);
    } catch (error) {
        // Already deleted (or expired).
        if (!(error instanceof ApiError && error.code === "not-found"))
            throw error;
    }
    project.poll = null;
    forgetPoll(project);
}

// Replace the poll by a new one, with new links (e.g. if a link was given to
// someone else): the previous links don't work anymore. The availabilities
// already imported are kept.
export async function resetPoll(api, project) {
    const {message} = project.poll;
    await deletePoll(api, project);
    newPoll(project, message);
}

// Fetch, decrypt and import the responses (see 'importResponses'). The
// responses which can't be decrypted are counted in 'invalid'.
export async function fetchResponses(api, project) {
    const {poll} = project;
    const encrypted = await api.readResponses(poll.id, poll.adminToken);
    const responses = [];
    let invalid = 0;
    for (const {id, data, updated} of encrypted) {
        try {
            responses.push({...normalizeResponse(await decrypt(poll.key, data)), id, updated});
        } catch (error) {
            invalid++;
        }
    }
    const summary = {...importResponses(project, responses), invalid, date: Date.now()};
    poll.lastImport = summary;
    return summary;
}

function normalizeName(name) {
    return name.trim().toLocaleLowerCase().replace(/\s+/g, " ");
}

// A decrypted response, checked.
export function normalizeResponse(response) {
    if (response === null || typeof response !== "object" || typeof response.name !== "string")
        throw new Error("invalid response");
    const availability = {};
    for (const [key, score] of Object.entries(response.availability || {})) {
        if (/^[0-6]:\d{1,4}$/.test(key) && (score === model.SCORE_PREFERRED || score === model.SCORE_POSSIBLE))
            availability[key] = score;
    }
    return {
        name: response.name.trim().slice(0, 100),
        availability,
        comment: typeof response.comment === "string"? response.comment.trim().slice(0, 1000): "",
    };
}

// Import responses '[{id, updated, name, availability, comment}]' into a
// project. A response is the one of:
// - the student of the personal link it was sent with, or for whom it was
//   imported before (even if the student changed their name);
// - otherwise, the student of the same name, if no response was imported for
//   them yet;
// - otherwise, a new student, with an individual course of 'duration'
//   minutes.
// The availabilities of the student are replaced by the ones of their latest
// response, unless it didn't change since it was imported (to keep the
// modifications of the teacher).
//
// Returns '{added: [name], updated: [name], unchanged: number}'.
export function importResponses(project, responses, duration = 30) {
    const summary = {added: [], updated: [], unchanged: 0};
    const ofResponse = (id) => project.participants.find((p) =>
        (p.pollLink !== undefined && p.pollLink.responseId === id)
        || (p.pollResponseIds !== undefined && p.pollResponseIds.includes(id)));
    for (const response of [...responses].sort((a, b) => a.updated - b.updated)) {
        let participant = ofResponse(response.id);
        if (participant === undefined) {
            if (response.name === "")
                continue;
            participant = project.participants.find((p) =>
                p.role !== "teacher"
                && (p.pollResponseIds === undefined || p.pollResponseIds.length === 0)
                && normalizeName(p.name) === normalizeName(response.name));
        }
        if (participant === undefined) {
            participant = model.addStudent(project, response.name, duration);
            summary.added.push(response.name);
        } else if (participant.pollUpdated !== undefined && participant.pollUpdated >= response.updated) {
            summary.unchanged++;
            continue;
        } else if (!summary.added.includes(participant.name) && !summary.updated.includes(participant.name)) {
            summary.updated.push(participant.name);
        }
        participant.availability = {...response.availability};
        if (response.comment === "")
            delete participant.comment;
        else
            participant.comment = response.comment;
        participant.pollResponseIds = [...new Set([...(participant.pollResponseIds || []), response.id])];
        participant.pollUpdated = response.updated;
    }
    ensurePersonalLinks(project);
    return summary;
}

/////////////////////////////////////////////////////////////////////////////
// Students
/////////////////////////////////////////////////////////////////////////////

// The decrypted definition of a poll, and whether it is closed.
export async function openPoll(api, pollId, key) {
    const {definition, closed} = await api.readPoll(pollId);
    const decrypted = await decrypt(key, definition);
    return {
        definition: {
            ...decrypted,
            calendar: model.normalizeCalendar(decrypted.calendar),
            teacherAvailability: decrypted.teacherAvailability || {},
        },
        closed,
    };
}

// The response sent with a personal link (e.g. from another device):
// '{name, availability, comment, updated}', or null if there is none yet.
export async function readOwnResponse(api, pollId, key, {responseId, token}) {
    let read;
    try {
        read = await api.readResponse(pollId, responseId, token);
    } catch (error) {
        if (error instanceof ApiError && error.code === "not-found")
            return null;
        throw error;
    }
    return {...normalizeResponse(await decrypt(key, read.data)), updated: read.updated};
}

// Send the response of a student. 'saved': '{responseId, token}' of a
// previous response or of a personal link, or null. Returns
// '{responseId, token}'.
export async function sendResponse(api, pollId, key, saved, response) {
    const {responseId, token} = saved || {responseId: randomToken(), token: randomToken()};
    const data = await encrypt(key, {version: FORMAT_VERSION, ...normalizeResponse(response)});
    await api.writeResponse(pollId, responseId, token, data);
    return {responseId, token};
}
